
  function seatRange(seats){if(!seats?.length)return"—";const s=[...seats].sort((a,b)=>a-b).map(i=>"S"+(i+1));return s.length===1?s[0]:s[0]+"–"+s.at(-1)}
  function filteredGuests(event){const q=ui.guestQuery.trim().toLocaleLowerCase("tr");return event.guests.filter(g=>{const t=g.assignment&&event.tables.find(x=>x.id===g.assignment.tableId),hay=[g.name,g.vip,g.invitedBy,g.notes,t?.number,g.planningStatus].join(" ").toLocaleLowerCase("tr");let filter=true;if(ui.guestFilter==="assigned")filter=!!g.assignment;if(ui.guestFilter==="unassigned")filter=!g.assignment;if(ui.guestFilter==="confirmed")filter=g.planningStatus==="Confirmed";if(ui.guestFilter==="tentative")filter=g.planningStatus==="Tentative";return(!q||hay.includes(q))&&filter})}
  function guestsHTML(event){const guests=filteredGuests(event);return`<div class="screen-scroll"><div class="screen-inner"><div class="screen-titlebar"><div><h2>${t("guests.title")}</h2><p>${t("guests.recordsSummary",{records:event.guests.length,total:eventMetrics(event).guests})}</p></div><div class="toolbar-row"><input class="filter-input" id="guestSearch" value="${esc(ui.guestQuery)}" placeholder="${t("guests.search")}"><select class="filter-input" id="guestFilter" style="width:128px"><option value="all">${t("guests.filter.all")}</option><option value="assigned" ${ui.guestFilter==="assigned"?"selected":""}>${t("guests.filter.assigned")}</option><option value="unassigned" ${ui.guestFilter==="unassigned"?"selected":""}>${t("guests.filter.unassigned")}</option><option value="confirmed" ${ui.guestFilter==="confirmed"?"selected":""}>${t("guests.filter.confirmed")}</option><option value="tentative" ${ui.guestFilter==="tentative"?"selected":""}>${t("guests.filter.tentative")}</option></select><button class="btn" data-guest-command="template">${icon("download")}${t("guests.excelTemplate")}</button><button class="btn" data-guest-command="import">${icon("image")}${t("guests.importExcel")}</button><button class="btn primary" data-guest-command="add">${icon("plus")}${t("guests.addGuest")}</button></div></div><div class="guest-shell"><table class="guest-table"><thead><tr><th>${t("guests.col.name")}</th><th>${t("guests.col.pax")}</th><th>${t("guests.col.status")}</th><th>${t("guests.col.vip")}</th><th>${t("guests.col.invitedBy")}</th><th>${t("guests.col.table")}</th><th>${t("guests.col.seat")}</th><th>${t("guests.col.notes")}</th><th>${t("guests.col.actions")}</th></tr></thead><tbody>${guests.length?guests.map(g=>guestRowHTML(event,g)).join(""):`<tr><td colspan="9" style="height:90px;text-align:center;color:var(--muted)">${t("guests.noMatches")}</td></tr>`}</tbody></table></div></div></div>`}
  function guestRowHTML(event,g){const t_=g.assignment&&event.tables.find(x=>x.id===g.assignment.tableId);return`<tr><td><span class="guest-name">${esc(g.name)}</span>${additionalOf(g)?`<span class="additional-note">${t("guests.additionalNote",{n:additionalOf(g),pax:paxOf(g)})}</span>`:""}</td><td class="mono">${paxOf(g)}</td><td><span class="status-chip ${g.planningStatus.toLowerCase()}">${esc(t("status.planning."+g.planningStatus))}</span></td><td><span class="vip-mark ${g.vip.toLowerCase()}">${esc(g.vip)}</span></td><td>${esc(g.invitedBy||"—")}</td><td>${t_?`<b>${esc(t_.number)}</b>${g.assignment.locked?" · 🔒":""}`:`<span class='muted'>${t("guests.unassigned")}</span>`}</td><td>${g.assignment?seatRange(g.assignment.seats):"—"}</td><td title="${esc(g.notes)}">${esc((g.notes||"—").slice(0,34))}</td><td><div class="row-actions"><button class="row-action" title="Open in Seating" data-guest-seat="${g.id}">${icon("seat")}</button><button class="row-action" title="Edit guest" data-guest-edit="${g.id}">${icon("edit")}</button><button class="row-action" title="Delete guest" data-guest-delete="${g.id}">${icon("trash")}</button></div></td></tr>`}
  function bindGuests(){const search=document.getElementById("guestSearch");search.oninput=()=>{ui.guestQuery=search.value;const p=search.selectionStart;render();requestAnimationFrame(()=>{const n=document.getElementById("guestSearch");n?.focus();n?.setSelectionRange(p,p)})};document.getElementById("guestFilter").onchange=e=>{ui.guestFilter=e.target.value;render()};app.querySelector("[data-guest-command='add']").onclick=()=>openGuestDialog();app.querySelector("[data-guest-command='import']").onclick=openExcelWizard;app.querySelector("[data-guest-command='template']").onclick=downloadExcelTemplate;app.querySelectorAll("[data-guest-edit]").forEach(b=>b.onclick=()=>openGuestDialog(b.dataset.guestEdit));app.querySelectorAll("[data-guest-delete]").forEach(b=>b.onclick=()=>deleteGuest(b.dataset.guestDelete));app.querySelectorAll("[data-guest-seat]").forEach(b=>b.onclick=()=>focusGuest(b.dataset.guestSeat))}
  function parseCompactName(value){const raw=String(value||"").trim(),match=raw.match(/^(.*?)\s*\+\s*(\d+)\s*$/);return match?{name:match[1].trim(),additionalGuests:Number(match[2]),detected:true}:{name:raw,additionalGuests:0,detected:false}}
  function openGuestDialog(id=null){const form=document.getElementById("guestForm"),fields=form.elements,g=id?activeEvent().guests.find(x=>x.id===id):null;form.reset();fields.id.value=g?.id||"";fields.name.value=g?.name||"";fields.additionalGuests.value=additionalOf(g||{pax:1});fields.planningStatus.value=g?.planningStatus||"Confirmed";fields.vip.value=g?.vip||"Standard";fields.invitedBy.value=g?.invitedBy||"";fields.notes.value=g?.notes||"";document.getElementById("guestTotalPax").textContent=String(paxOf(g||{pax:1}));document.getElementById("guestDialogTitle").textContent=g?"Edit Guest":"Add Guest";document.getElementById("guestDialog").showModal();setTimeout(()=>fields.name.focus(),30)}
  document.getElementById("guestForm").elements.additionalGuests.addEventListener("input",e=>document.getElementById("guestTotalPax").textContent=String(1+Math.max(0,Number(e.target.value)||0)));
  document.getElementById("guestForm").addEventListener("submit",e=>{e.preventDefault();const f=new FormData(e.currentTarget),event=activeEvent(),id=f.get("id"),existing=event.guests.find(g=>g.id===id),compact=parseCompactName(f.get("name"));let additional=Math.max(0,Number(f.get("additionalGuests"))||0);if(compact.detected&&additional===0)additional=compact.additionalGuests;const pax=1+additional;if(!compact.name){toast("Name Surname is required.","error");return}if(existing?.assignment){const t=event.tables.find(x=>x.id===existing.assignment.tableId),others=tableAssignedPax(event,t.id)-paxOf(existing);if(others+pax>t.capacity){toast(`${t.number} has only ${t.capacity-others} seats available for this record.`,"error");return}existing.additionalGuests=additional;existing.pax=pax;repackTableAssignments(event,t,t.capacity)}const data={name:compact.name,additionalGuests:additional,pax,planningStatus:f.get("planningStatus"),vip:f.get("vip"),invitedBy:String(f.get("invitedBy")).trim(),notes:String(f.get("notes")).trim()};if(existing)Object.assign(existing,data);else event.guests.unshift({id:uid("guest"),...data,arrivalStatus:"Not Arrived",assignment:null,createdAt:nowISO()});touchEvent(event);document.getElementById("guestDialog").close();render();toast(existing?"Guest updated.":"Guest added.","success")});
  function deleteGuest(id){const event=activeEvent(),g=event.guests.find(x=>x.id===id);if(!g||!confirm(`Delete ${g.name} from the guest list?`))return;event.guests=event.guests.filter(x=>x.id!==id);touchEvent(event);render();toast("Guest deleted.")}

  function wizardStepsHTML(step){const labels=["Choose File","Source Preview","Column Mapping","Interpretation","Summary"];return`<div class="wizard-steps">${labels.map((l,i)=>`<div class="wizard-step ${step===i+1?"active":step>i+1?"done":""}"><i>${step>i+1?"✓":i+1}</i><span>${l}</span></div>`).join("")}</div>`}
  function openExcelWizard(){pendingImport={step:1,fileName:"",rows:[],headers:[],mapping:{},interpreted:[]};renderExcelWizard();document.getElementById("excelDialog").showModal()}
  function renderExcelWizard(){const root=document.getElementById("excelWizard"),p=pendingImport;if(!p)return;root.innerHTML=`<div class="dialog-head"><h2>Import Guest List</h2><button class="dialog-close" data-wizard-close aria-label="Close">×</button></div>${wizardStepsHTML(p.step)}<div class="dialog-body">${wizardBodyHTML(p)}</div><div class="dialog-foot">${wizardFootHTML(p)}</div>`;bindExcelWizard()}
  function wizardBodyHTML(p){if(p.step===1)return`<div class="drop-zone">${icon("download")}<h3>Choose Excel or CSV file</h3><p>Nothing is imported until you review source rows, mapping and interpretation.</p><div class="toolbar-row"><button class="btn" data-wizard-template>${icon("download")}Download Excel Template</button><button class="btn primary" data-wizard-choose>${icon("plus")}Choose File</button></div></div>`;if(p.step===2)return`<div class="screen-titlebar"><div><h2>Preview Source Data</h2><p>${esc(p.fileName)} · showing the first ${Math.min(15,p.rows.length)} of ${p.rows.length} rows exactly as read.</p></div></div><div class="source-scroll">${sourcePreviewHTML(p)}</div>`;if(p.step===3)return`<div class="screen-titlebar"><div><h2>Column Mapping</h2><p>Map at least one column to Name Surname. Unneeded columns can be ignored.</p></div></div><div style="max-width:760px">${mappingRowsHTML(p)}</div>`;if(p.step===4)return`<div class="screen-titlebar"><div><h2>Interpretation Preview</h2><p>Review exactly how each source row will become a guest record. Edit any incorrect value before continuing.</p></div></div><div class="source-scroll"><table class="preview-table interpret-table"><thead><tr><th>Source</th><th>Name Surname</th><th>Additional</th><th>Total Pax</th><th>Status</th><th>VIP</th><th>Table</th><th>Seat</th><th>Validation</th></tr></thead><tbody>${p.interpreted.map((r,i)=>interpretRowHTML(r,i)).join("")}</tbody></table></div>`;const s=importSummary(p.interpreted);return`<div class="screen-titlebar"><div><h2>Import Summary</h2><p>Final review. Existing data will not be replaced.</p></div></div><div class="wizard-summary"><div><span>Records</span><b>${s.records}</b></div><div><span>Total Guests</span><b>${s.guests}</b></div><div><span>Confirmed</span><b>${s.confirmed}</b></div><div><span>Tentative</span><b>${s.tentative}</b></div><div><span>Needs Attention</span><b>${s.attention}</b></div></div>${s.errors?`<div class="guide-tip guide-warning" style="margin-top:14px">${s.errors} row${s.errors===1?"":"s"} contain blocking errors. Go back to Interpretation and fix them before importing.</div>`:`<div class="guide-tip" style="margin-top:14px">Ready to import ${s.records} records representing ${s.guests} physical guests.</div>`}`}
  function wizardFootHTML(p){if(p.step===1)return`<button class="btn" data-wizard-close>Cancel</button>`;if(p.step===2)return`<button class="btn" data-wizard-back>Back</button><button class="btn primary" data-wizard-next>Continue to Mapping${icon("arrow")}</button>`;if(p.step===3)return`<button class="btn" data-wizard-back>Back</button><button class="btn primary" data-wizard-next>Interpret Rows${icon("arrow")}</button>`;if(p.step===4)return`<button class="btn" data-wizard-back>Back</button><button class="btn primary" data-wizard-next>Review Summary${icon("arrow")}</button>`;const s=importSummary(p.interpreted);return`<button class="btn" data-wizard-back>Back</button><button class="btn primary" data-wizard-import ${s.errors?"disabled":""}>Import Guests</button>`}
  function sourcePreviewHTML(p){return`<table class="preview-table"><thead><tr><th>#</th>${p.headers.map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${p.rows.slice(0,15).map((row,i)=>`<tr><td>${i+1}</td>${p.headers.map(h=>`<td>${esc(row[h])}</td>`).join("")}</tr>`).join("")}</tbody></table>`}
  const MAP_FIELDS=[["","Ignore Column"],["name","Name Surname"],["pax","Total Pax"],["additionalGuests","Additional Guests"],["planningStatus","Status"],["vip","VIP Level"],["invitedBy","Invited By"],["notes","Notes"],["existingTable","Existing Table"],["existingSeat","Existing Seat"]];
  function mappingRowsHTML(p){return p.headers.map(h=>`<div class="mapping-grid"><div class="mapping-source" title="${esc(h)}">${esc(h)}</div><div class="mapping-arrow">→</div><select class="filter-input" data-map-header="${esc(h)}">${MAP_FIELDS.map(([v,l])=>`<option value="${v}" ${p.mapping[h]===v?"selected":""}>${l}</option>`).join("")}</select></div>`).join("")}
  function interpretRowHTML(r,i){const issues=r.issues||[];return`<tr><td title="${esc(r.sourceName)}">${esc(r.sourceName)}</td><td><input data-interp-row="${i}" data-interp-field="name" value="${esc(r.name)}"></td><td><input data-interp-row="${i}" data-interp-field="additionalGuests" type="number" min="0" value="${r.additionalGuests}"></td><td><b>${r.pax}</b></td><td><select data-interp-row="${i}" data-interp-field="planningStatus"><option ${r.planningStatus==="Confirmed"?"selected":""}>Confirmed</option><option ${r.planningStatus==="Tentative"?"selected":""}>Tentative</option></select></td><td><select data-interp-row="${i}" data-interp-field="vip">${["Standard","VIP","VVIP"].map(v=>`<option ${r.vip===v?"selected":""}>${v}</option>`).join("")}</select></td><td><input data-interp-row="${i}" data-interp-field="tableNumber" value="${esc(r.tableNumber||"")}"></td><td><input data-interp-row="${i}" data-interp-field="seatText" value="${esc(r.seatText||"")}"></td><td>${issues.length?issues.map(x=>`<div class="issue ${x.level}">⚠ ${esc(x.message)}</div>`).join(""):`<span style="color:#83b996">✓ Ready</span>`}</td></tr>`}
  function bindExcelWizard(){const p=pendingImport;document.querySelectorAll("[data-wizard-close]").forEach(b=>b.onclick=()=>{document.getElementById("excelDialog").close();pendingImport=null});const choose=document.querySelector("[data-wizard-choose]");if(choose)choose.onclick=()=>document.getElementById("guestFileInput").click();const template=document.querySelector("[data-wizard-template]");if(template)template.onclick=downloadExcelTemplate;const back=document.querySelector("[data-wizard-back]");if(back)back.onclick=()=>{p.step=Math.max(1,p.step-1);renderExcelWizard()};const next=document.querySelector("[data-wizard-next]");if(next)next.onclick=()=>{if(p.step===2){p.step=3}else if(p.step===3){document.querySelectorAll("[data-map-header]").forEach(s=>p.mapping[s.dataset.mapHeader]=s.value);if(!Object.values(p.mapping).includes("name")){toast("Map one column to Name Surname.","error");return}p.interpreted=interpretImportRows(p.rows,p.mapping,activeEvent());p.step=4}else if(p.step===4){revalidateInterpreted(p.interpreted,activeEvent());p.step=5}renderExcelWizard()};document.querySelectorAll("[data-interp-row]").forEach(el=>el.onchange=()=>{const r=p.interpreted[Number(el.dataset.interpRow)],field=el.dataset.interpField;r[field]=field==="additionalGuests"?Math.max(0,Number(el.value)||0):el.value;if(field==="additionalGuests"){r.pax=1+r.additionalGuests;r.issues=(r.issues||[]).filter(x=>!x.message.includes("Invalid additional guest")&&!x.message.includes("Invalid total pax"))}revalidateInterpreted(p.interpreted,activeEvent());renderExcelWizard()});const imp=document.querySelector("[data-wizard-import]");if(imp)imp.onclick=importInterpretedGuests}
  document.getElementById("guestFileInput").addEventListener("change",async e=>{const file=e.target.files[0];if(!file)return;try{let rows=[];if(file.name.toLowerCase().endsWith(".csv"))rows=parseCSV(await file.text());else{await loadXLSX();const data=await file.arrayBuffer(),book=XLSX.read(data,{type:"array"}),sheet=book.Sheets[book.SheetNames[0]];rows=XLSX.utils.sheet_to_json(sheet,{defval:"",raw:false})}if(!rows.length)throw new Error("The selected file contains no data rows.");pendingImport={step:2,fileName:file.name,rows,headers:Object.keys(rows[0]),mapping:autoMapping(Object.keys(rows[0])),interpreted:[]};if(!document.getElementById("excelDialog").open)document.getElementById("excelDialog").showModal();renderExcelWizard()}catch(err){console.error(err);toast(err.message||"Could not read this guest list.","error",5200)}e.target.value=""});
  function parseCSV(text){const lines=[];let row=[],cell="",quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===","&&!quoted){row.push(cell);cell=""}else if((c==="\n"||c==="\r")&&!quoted){if(c==="\r"&&n==="\n")i++;row.push(cell);if(row.some(x=>x!==""))lines.push(row);row=[];cell=""}else cell+=c}row.push(cell);if(row.some(x=>x!==""))lines.push(row);if(lines.length<2)return[];const headers=lines[0].map((h,i)=>h.trim()||`Column ${i+1}`);return lines.slice(1).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??""])))}
  function loadXLSX(){return window.XLSX?Promise.resolve():Promise.reject(new Error("Embedded spreadsheet engine did not initialize."))}
  function norm(v){return String(v).toLowerCase().replace(/[^a-z0-9ğüşöçı]+/g,"")}
  function autoMapping(headers){const aliases={name:["name","namesurname","guestname","fullname","guest","misafir","adsoyad","isim"],pax:["pax","totalpax","totalguests","guests","kisi","kişi","adet"],additionalGuests:["additionalguests","additional","plus","ekmisafir","refakatci"],planningStatus:["status","planningstatus","durum"],vip:["vip","viplevel","level"],invitedBy:["invitedby","marketing","host","daveteden"],notes:["notes","note","not","aciklama","açıklama"],existingTable:["table","tablenumber","masa"],existingSeat:["seat","seats","koltuk"]},map={};headers.forEach(h=>{const n=norm(h);for(const[field,list]of Object.entries(aliases))if(list.some(a=>norm(a)===n)){map[h]=field;break}});return map}
  function mappedValue(row,mapping,field){const key=Object.keys(mapping).find(k=>mapping[k]===field);return key===undefined?"":row[key]}
  function parsePlanningStatus(value){const n=norm(value);if(["confirmed","kesin","definite","yes"].includes(n))return{value:"Confirmed",known:true};if(["tentative","belirsiz","uncertain","maybe"].includes(n))return{value:"Tentative",known:true};if(!n)return{value:"Confirmed",known:true};return{value:"Tentative",known:false}}
  function parseVip(value){const n=String(value||"").trim().toUpperCase();return["VIP","VVIP"].includes(n)?n:"Standard"}
  function parseSeatText(value){const out=[],re=/S?\s*(\d+)(?:\s*[-–]\s*S?\s*(\d+))?/gi,text=String(value||"");let m;while((m=re.exec(text))){const first=Number(m[1]),last=m[2]?Number(m[2]):first,step=last>=first?1:-1;if(Math.abs(last-first)>98){out.push(first-1);continue}for(let n=first;n!==last+step;n+=step)out.push(n-1)}return out}
  function interpretImportRows(rows,mapping,event){const interpreted=rows.map((row,index)=>{const sourceName=String(mappedValue(row,mapping,"name")||"").trim(),compact=parseCompactName(sourceName),addRaw=mappedValue(row,mapping,"additionalGuests"),paxRaw=mappedValue(row,mapping,"pax"),status=parsePlanningStatus(mappedValue(row,mapping,"planningStatus"));let additional=compact.additionalGuests,issues=[];if(String(addRaw).trim()!==""){const n=Number(addRaw);if(!Number.isInteger(n)||n<0)issues.push({level:"error",message:"Invalid additional guest number."});else additional=n}else if(String(paxRaw).trim()!==""){const n=Number(paxRaw);if(!Number.isInteger(n)||n<1)issues.push({level:"error",message:"Invalid total pax."});else additional=n-1}if(compact.detected&&String(addRaw).trim()!==""&&Number(addRaw)!==compact.additionalGuests)issues.push({level:"warn",message:"+N differs from Additional Guests; mapped column is used."});if(!status.known)issues.push({level:"warn",message:"Unknown status changed to Tentative."});return{sourceIndex:index,sourceName,name:compact.name,additionalGuests:Math.max(0,Number(additional)||0),pax:1+Math.max(0,Number(additional)||0),planningStatus:status.value,vip:parseVip(mappedValue(row,mapping,"vip")),invitedBy:String(mappedValue(row,mapping,"invitedBy")||"").trim(),notes:String(mappedValue(row,mapping,"notes")||"").trim(),tableNumber:String(mappedValue(row,mapping,"existingTable")||"").trim().toUpperCase(),seatText:String(mappedValue(row,mapping,"existingSeat")||"").trim(),issues}});revalidateInterpreted(interpreted,event);return interpreted}
  function revalidateInterpreted(rows,event){const counts=new Map(),pendingSeats=new Map();rows.forEach(r=>counts.set(norm(r.name),(counts.get(norm(r.name))||0)+1));rows.forEach(r=>{const preserved=(r.issues||[]).filter(x=>x.message.includes("mapped column")||x.message.includes("Unknown status")||x.message.includes("Invalid additional guest")||x.message.includes("Invalid total pax"));r.issues=preserved;r.additionalGuests=Math.max(0,Number(r.additionalGuests)||0);r.pax=1+r.additionalGuests;if(!String(r.name).trim())r.issues.push({level:"error",message:"Name is empty."});const key=norm(r.name);if(key&&(counts.get(key)>1||event.guests.some(g=>norm(g.name)===key)))r.issues.push({level:"warn",message:"Possible duplicate name."});if(r.tableNumber){const t=event.tables.find(x=>x.number.toUpperCase()===r.tableNumber.toUpperCase());if(!t){r.issues.push({level:"error",message:"Table number does not exist."});return}const seats=parseSeatText(r.seatText),used=occupiedSeatIndexes(event,t.id),pending=pendingSeats.get(t.id)||new Set();pendingSeats.set(t.id,pending);if(seats.length){const chosen=seats.slice(0,r.pax);if(seats.some(s=>s<0||s>=t.capacity))r.issues.push({level:"error",message:"Seat number is outside table capacity."});if(seats.length<r.pax)r.issues.push({level:"error",message:"Not enough seat numbers for total pax."});if(new Set(chosen).size<chosen.length)r.issues.push({level:"error",message:"The same seat number is listed more than once."});if(chosen.some(s=>used.has(s)||pending.has(s)))r.issues.push({level:"error",message:"One or more seats are already assigned."});if(!r.issues.some(x=>x.level==="error"))chosen.forEach(s=>pending.add(s))}else{const free=Array.from({length:t.capacity},(_,i)=>i).filter(i=>!used.has(i)&&!pending.has(i));if(free.length<r.pax)r.issues.push({level:"error",message:"Table does not have enough available seats."});else free.slice(0,r.pax).forEach(s=>pending.add(s))}}})}
  function importSummary(rows){return{records:rows.length,guests:rows.reduce((n,r)=>n+r.pax,0),confirmed:rows.filter(r=>r.planningStatus==="Confirmed").length,tentative:rows.filter(r=>r.planningStatus==="Tentative").length,attention:rows.filter(r=>r.issues?.length).length,errors:rows.filter(r=>r.issues?.some(x=>x.level==="error")).length}}
  function importInterpretedGuests(){const p=pendingImport,event=activeEvent(),summary=importSummary(p.interpreted);if(summary.errors){toast("Fix blocking import errors first.","error");return}let assigned=0;p.interpreted.forEach(r=>{const g={id:uid("guest"),name:String(r.name).trim(),additionalGuests:r.additionalGuests,pax:r.pax,planningStatus:r.planningStatus,vip:r.vip,invitedBy:r.invitedBy,notes:r.notes,arrivalStatus:"Not Arrived",assignment:null,createdAt:nowISO()};if(r.tableNumber){const t=event.tables.find(x=>x.number.toUpperCase()===r.tableNumber.toUpperCase()),used=occupiedSeatIndexes(event,t.id);let seats=parseSeatText(r.seatText);if(!seats.length)seats=Array.from({length:t.capacity},(_,i)=>i).filter(i=>!used.has(i)).slice(0,g.pax);if(seats.length>=g.pax&&!seats.slice(0,g.pax).some(i=>used.has(i))){g.assignment={tableId:t.id,seats:seats.slice(0,g.pax),locked:false};assigned++}}event.guests.push(g)});touchEvent(event);document.getElementById("excelDialog").close();pendingImport=null;render();toast(`${summary.records} guest records imported${assigned?` · ${assigned} assigned`:""}.`,"success",5000)}
