  function tableSeatMap(event,tableId){const map=new Map();event.guests.filter(g=>g.assignment?.tableId===tableId).forEach(g=>{g.assignment.seats.forEach((seat,i)=>map.set(seat,{guest:g,companion:i>0,index:i}))});return map}
  function selectedTablePanelHTML(event){if(ui.rightCollapsed)return collapsedPanel("right");const t=event.tables.find(x=>x.id===ui.selectedTableId);if(!t)return`<aside class="side-panel right"><div class="panel-head"><strong>Selected Table</strong><button class="panel-toggle" data-panel-toggle="right">${icon("chevron")}</button></div><div class="inspector-empty">Select a table to review capacity, occupied seats and guest names.</div></aside>`;const map=tableSeatMap(event,t.id),occupied=tableAssignedPax(event,t.id),empty=Math.max(0,t.capacity-occupied),selected=event.guests.find(g=>g.id===ui.selectedGuestId);return`<aside class="side-panel right"><div class="panel-head"><strong>Selected Table</strong><button class="panel-toggle" data-panel-toggle="right">${icon("chevron")}</button></div><div class="table-summary"><h3>${esc(formatTableNumber(t.number))}</h3><div class="occupancy-strip"><div class="occupancy-stat"><span>Capacity</span><b>${t.capacity}</b></div><div class="occupancy-stat"><span>Occupied</span><b>${occupied}</b></div><div class="occupancy-stat"><span>Empty</span><b>${empty}</b></div></div>${selected?`<button class="btn primary sm" style="width:100%;margin-top:10px" data-assign-selected="${t.id}">${selected.assignment&&selected.assignment.tableId!==t.id?"Move":"Assign"} ${esc(selected.name)} (${paxOf(selected)} seats)</button>`:`<div class="dialog-note" style="margin-top:9px">Select a guest on the left, then assign the required number of seats.</div>`}</div><div class="seat-list">${Array.from({length:t.capacity},(_,i)=>seatRowHTML(i,map.get(i),selected)).join("")}</div></aside>`}
  function seatRowHTML(index,occupant,selected){if(!occupant)return`<div class="seat-row empty" data-empty-seat="${index}"><span class="seat-no">S${index+1}</span><span class="seat-person">Empty</span>${selected?"<button class='seat-action'>Assign here</button>":"<span></span>"}</div>`;const g=occupant.guest,label=occupant.companion?`GUEST OF ${g.name.toUpperCase()}`:g.name;return`<div class="seat-row"><span class="seat-no">S${index+1}</span><span class="seat-person">${esc(label)} ${occupant.companion?"<small>companion</small>":""}</span>${occupant.index===0?`<span><button class="seat-action" data-lock-assignment="${g.id}">${g.assignment.locked?"Unlock":"Lock"}</button> <button class="seat-action" data-unassign="${g.id}">Unassign</button></span>`:"<span></span>"}</div>`}
  function bindSeating(){bindPanelToggles();const search=document.getElementById("seatingSearch");if(search)search.oninput=()=>{ui.seatingQuery=search.value;const p=search.selectionStart;render();requestAnimationFrame(()=>{const n=document.getElementById("seatingSearch");n?.focus();n?.setSelectionRange(p,p)})};app.querySelectorAll("[data-seating-scope]").forEach(b=>b.onclick=()=>{ui.seatingGuestScope=b.dataset.seatingScope;ui.selectedGuestId=null;render()});app.querySelectorAll("[data-seating-filter]").forEach(b=>b.onclick=()=>{ui.seatingFilter=b.dataset.seatingFilter;render()});app.querySelectorAll("[data-seating-guest]").forEach(row=>{row.onclick=()=>{ui.selectedGuestId=row.dataset.seatingGuest;render()};row.ondragstart=e=>e.dataTransfer.setData("application/x-merit-guest",row.dataset.seatingGuest)});const assign=app.querySelector("[data-assign-selected]");if(assign)assign.onclick=()=>assignGuestToTable(ui.selectedGuestId,assign.dataset.assignSelected);app.querySelectorAll("[data-empty-seat]").forEach(row=>row.onclick=()=>{if(ui.selectedGuestId)assignGuestToTable(ui.selectedGuestId,ui.selectedTableId,Number(row.dataset.emptySeat))});app.querySelectorAll("[data-unassign]").forEach(b=>b.onclick=()=>unassignGuest(b.dataset.unassign));app.querySelectorAll("[data-lock-assignment]").forEach(b=>b.onclick=()=>toggleAssignmentLock(b.dataset.lockAssignment))}
  function assignGuestToTable(guestId,tableId,preferred=null){const event=activeEvent(),g=event.guests.find(x=>x.id===guestId),t=event.tables.find(x=>x.id===tableId);if(!g||!t)return;const moving=!!g.assignment&&g.assignment.tableId!==tableId;if(g.assignment?.locked){toast(`${g.name}'s assignment is locked. Unlock it before moving.`,"error");return}const used=occupiedSeatIndexes(event,tableId,g.id),free=Array.from({length:t.capacity},(_,i)=>i).filter(i=>!used.has(i));if(free.length<paxOf(g)){toast(`${t.number} has only ${free.length} available seats. ${g.name} requires ${paxOf(g)}.`,"error",5000);return}let seats=[];if(preferred!==null&&free.includes(preferred)){seats=[preferred,...free.filter(i=>i!==preferred).slice(0,paxOf(g)-1)]}else seats=free.slice(0,paxOf(g));g.assignment={tableId,seats,locked:false};ui.selectedTableId=tableId;ui.highlightId=tableId;touchEvent(event);render();toast(`${g.name} ${moving?"moved to":"assigned to"} ${t.number} · ${paxOf(g)} seats reserved.`,"success")}
